window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[54]={"id":"054","numero":54,"titre":"Boiterie chez l'enfant","objectifs":[{"id":"54-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la boiterie de l’enfant","contenu":"<p>La <span class=\"kw-def\">boiterie</span> correspond à une <strong>anomalie récente de la marche, qui devient asymétrique</strong>. Elle est à <em>distinguer</em> des troubles de la démarche anciens ou apparus depuis l’acquisition de la marche.</p>\n\n      <h4>Deux grands types sémiologiques</h4>\n\n      <table >\n        <thead>\n          <tr><th>Type</th><th>Description</th><th>Traduction</th><th>Causes</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Boiterie d’esquive</strong><br><em>(ou <span class=\"kw-ttt\">antalgique</span>)</em></td>\n            <td>L’enfant évite ou <strong>raccourcit le temps d’appui</strong> du côté pathologique et déporte le poids de son corps du côté opposé</td>\n            <td>Douleur du membre inférieur</td>\n            <td>Étiologies développées dans ce cours (toutes causes douloureuses)</td>\n          </tr>\n          <tr>\n            <td><strong>Boiterie d’épaule</strong><br><em>ou d’équilibration<br>(Trendelenburg)</em></td>\n            <td><span class=\"kw-clinique\">Les</span> <strong>épaules basculent à chaque appui</strong> du côté pathologique par <span class=\"kw-clinique\">insuffisance des muscles fessiers</span></td>\n            <td>Pathologie chronique de la hanche</td>\n            <td>\n              <ul>\n                <li>Neurologiques</li>\n                <li>Orthopédiques</li>\n                <li>Musculaires</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Causes urgentes à toujours évoquer</h4>\n\n      <ul>\n        <li><span class=\"kw-alerte\">Fracture</span></li>\n        <li><span class=\"kw-alerte\">Infection ostéo-articulaire</span> (IOA) — à tout âge, surtout si <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">infectieux</span></span></li>\n        <li><span class=\"kw-alerte\">Épiphysiolyse fémorale supérieure</span> (EFS) — chez l’adolescent</li>\n        <li><span class=\"kw-alerte\">Tumeur osseuse</span>, <span class=\"kw-alerte\">leucémie</span> — plus rare</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège diagnostique.</strong> Un <em>psoïtis</em> (ex : <span class=\"kw-clinique\">appendicite</span> aiguë) peut entraîner des difficultés à la marche et mimer une boiterie d’origine orthopédique. À évoquer systématiquement.\n      </div>","frequence":1},{"id":"54-2","rang":"A","rubrique":"Définition","titre":"Boiterie fébrile : toujours rechercher une infection ostéoarticulaire","contenu":"<div class=\"callout callout-warn\">\n        <strong>Règle d’or EDN.</strong> Toute <em>boiterie fébrile chez l’enfant</em> est une <span class=\"kw-alerte\">infection ostéo-articulaire jusqu’à preuve du contraire</span> 🔥. Le bilan <span class=\"kw-ttt\">biologique</span> et l’imagerie sont à réaliser <strong>en <span class=\"kw-alerte\">urgence</span></strong>.\n      </div>\n\n      <h4>Bilan à réaliser en <span class=\"kw-alerte\">urgence</span> devant une boiterie fébrile</h4>\n\n      <table >\n        <thead>\n          <tr><th>Axe</th><th>Examens</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Biologie</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-bio\">NFS</span></strong> · <strong><span class=\"kw-bio\">CRP</span></strong> (± <span class=\"kw-bio\">VS</span>)</li>\n                <li><strong><span class=\"kw-bio\">Hémocultures</span></strong> : <span class=\"kw-chiffre\">2 paires</span> avant toute <span class=\"kw-ttt\">antibiothérapie</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Imagerie</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-imagerie\">RX face + profil</span> centrées sur la zone douloureuse</li>\n                <li><span class=\"kw-imagerie\">Échographie</span> articulaire (épanchement de hanche/cheville, <span class=\"kw-clinique\">abcès</span> sous-périosté)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Prélèvements bactériologiques</strong><br><em>(avant ATB)</em></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-bio\">Hémocultures</span> (×2)</li>\n                <li>Si arthrite : <span class=\"kw-ttt\">ponction</span> articulaire (sous AG au bloc)</li>\n                <li>Si <span class=\"kw-clinique\">abcès</span> sous-périosté : prélèvement de pus au bloc</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Différentiels à éliminer</h4>\n\n      <ul>\n        <li><strong>Synovite aiguë transitoire</strong> (« rhume de la hanche ») : <em>non fébrile</em>, diagnostic d’élimination</li>\n        <li><strong>Arthrite juvénile idiopathique</strong> : absence de <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-bio\">syndrome inflammatoire</span> souvent modéré voire absent</li>\n        <li><strong>Pathologies tumorales</strong> : horaire <span class=\"kw-etio\">inflammatoire</span> des douleurs doit alerter</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-etio\">Sepsis</span> · 147 — <span class=\"kw-clinique\">Fièvre</span> aiguë chez l’enfant · 156 — Infections ostéo-articulaires</em></p>","frequence":3},{"id":"54-3","rang":"A","rubrique":"Diagnostic positif","titre":"Boiterie de l’enfant : connaître les éléments de l’interrogatoire et de l’examen clinique","contenu":"<p>La démarche repose sur un <span class=\"kw-def\">interrogatoire orienté</span> et un <strong>examen clinique systématique</strong>, déchaussé et dévêtu chez l’enfant.</p>\n\n      <h4>Interrogatoire</h4>\n\n      <table >\n        <thead>\n          <tr><th>Axe</th><th>Éléments à rechercher</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span></strong></td>\n            <td>\n              <ul>\n                <li><strong>Âge</strong> : la majorité des pathologies orthopédiques pédiatriques ont un <em>âge de prédilection</em></li>\n                <li><strong>ATCD</strong> : prématurité, <span class=\"kw-alerte\">asphyxie</span> périnatale, drépanocytose, <span class=\"kw-etio\">obésité</span></li>\n                <li>Développement <strong>psychomoteur</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Circonstances</strong></td>\n            <td>\n              <ul>\n                <li>Contexte <span class=\"kw-etio\">infectieux</span> : <span class=\"kw-clinique\">fièvre</span>, porte d’entrée cutanée (plaie, varicelle), infection ORL récente</li>\n                <li>Traumatisme récent (chute), corps étranger du pied</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Symptomatologie</strong></td>\n            <td>\n              <ul>\n                <li>Caractéristiques de la boiterie : <strong>brutale ou progressive</strong>, ancienneté, <span class=\"kw-clinique\">évolution</span>, permanente ou intermittente</li>\n                <li>Si douleur : date d’apparition, localisation (difficile à préciser chez le nourrisson)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>3 pièges classiques de l’interrogatoire.</strong>\n        <ul>\n          <li>Douleurs du genou secondaires à une atteinte de la <strong>hanche</strong> (<em>douleurs projetées</em>)</li>\n          <li>Épisode traumatique antérieur (banal et quotidien chez l’enfant) faussement évoqué comme cause : rester vigilant</li>\n          <li><strong>Psoïtis</strong> susceptible d’entraîner des difficultés à la marche (ex : <span class=\"kw-clinique\">appendicite</span> aiguë)</li>\n        </ul>\n      </div>\n\n      <h4>Examen clinique</h4>\n\n      <p>Chez le <strong>petit enfant</strong> (origine difficile à repérer) → méthode <em>très systématique</em> à la recherche du siège de la douleur, enfant dévêtu et déchaussé. Chez le <strong>grand enfant et l’adolescent</strong> → focalisation sur la région douloureuse identifiée.</p>\n\n      <table >\n        <thead>\n          <tr><th>Étape</th><th>Recherche</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1 — Observation de la boiterie</strong></td>\n            <td>Caractériser : esquive <span class=\"kw-bio\">vs</span> équilibration (cf. <em>obj-0</em>)</td>\n          </tr>\n          <tr>\n            <td><strong>2 — Inspection</strong></td>\n            <td>\n              <ul>\n                <li>Attitude vicieuse du membre inférieur</li>\n                <li><span class=\"kw-clinique\">Lésion</span> cutanée (en particulier plantaire)</li>\n                <li><strong>Amyotrophie quadricipitale</strong> = <span class=\"kw-clinique\">signe formel d’organicité et d’ancienneté</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>3 — Palpation méthodique</strong></td>\n            <td>\n              Commencer par l’extrémité <strong>distale</strong> et remonter jusqu’à la hanche :\n              <ul>\n                <li><em>Diaphyse tibiale</em> : palpation attentive (fracture sous-périostée), mouvement de torsion</li>\n                <li><em>Métaphyses</em> : douleur à la palpation, chaleur, rougeur, <span class=\"kw-clinique\">tuméfaction</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>4 — Mobilisation articulaire</strong></td>\n            <td>\n              Douleur provoquée ou déficit d’amplitude (comparaison avec le côté opposé).\n              <span class=\"kw-clinique\">Limitation de l’abduction et de la rotation interne</span> = retrouvée dans <strong>toute atteinte de la hanche</strong>, quelle qu’en soit la cause.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>5 — Genou</strong></td>\n            <td>Épanchement : comblement du cul-de-sac sous-quadricipital + <strong><span class=\"kw-alerte\">choc</span> rotulien</strong></td>\n          </tr>\n          <tr>\n            <td><strong>6 — Rachis</strong></td>\n            <td>\n              <ul>\n                <li>Douleur à la palpation</li>\n                <li>Raideur</li>\n                <li><strong>Refus de la station assise</strong> = parfois seul signe objectif d’atteinte rachidienne</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>7 — Examen neurologique</strong></td>\n            <td>Marche en équin, tonus, force musculaire, ROT</td>\n          </tr>\n          <tr>\n            <td><strong>8 — Examen cutané</strong></td>\n            <td><span class=\"kw-clinique\">Ecchymoses</span>, porte d’entrée infectieuse, plaie</td>\n          </tr>\n          <tr>\n            <td><strong>9 — Examen général</strong></td>\n            <td>Systématique (palpation abdominale, ORL…)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> <span class=\"kw-clinique\">Les</span> atteintes de hanche ne représentent que <span class=\"kw-chiffre\">&lt; 40 %</span> des boiteries — penser systématiquement à examiner <em>l’ensemble du membre inférieur + le rachis + l’abdomen</em>.\n      </div>","frequence":2},{"id":"54-4","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires à réaliser devant une boiterie de l’enfant","contenu":"<p>La hiérarchisation des examens dépend du <strong>contexte fébrile ou non</strong> et de la <em>localisation</em> identifiée par l’examen clinique.</p>\n\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Indications · résultats à interpréter</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">RX (face + profil)</span></strong></td>\n            <td>\n              <ul>\n                <li>Centrées sur la zone douloureuse — si clinique ne localise pas : <em>l’ensemble du membre est radiographié</em></li>\n                <li><strong>Pas de clichés comparatifs</strong></li>\n                <li><strong>Ostéomyélite aiguë</strong> : RX initiales <em>normales</em></li>\n                <li><strong>Arthrite septique</strong> : signes indirects d’épanchement (épaississement parties molles, élargissement de l’interligne articulaire)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Échographie</span></strong></td>\n            <td>\n              <ul>\n                <li>Objectiver un <strong>épanchement articulaire</strong> (hanche, cheville)</li>\n                <li><strong>Ostéomyélite</strong> : épaississement des parties molles, <span class=\"kw-clinique\">abcès</span> sous-périosté</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Scintigraphie osseuse</span><br>au technétium 99</strong></td>\n            <td>\n              <ul>\n                <li>Demandée <em>en dehors d’une situation d’<span class=\"kw-alerte\">urgence</span></em> pour confirmer un IOA</li>\n                <li>Utile chez le <strong>jeune enfant difficile à examiner</strong> → localise le site lésionnel (hyperfixation pathologique)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">IRM</span></strong></td>\n            <td>\n              <ul>\n                <li>Diagnostic d’<strong>ostéomyélite à la phase précoce</strong> si zone douloureuse identifiée</li>\n                <li>Visualise <span class=\"kw-clinique\">les</span> <strong>complications</strong> (arthrite associée, <span class=\"kw-clinique\">abcès</span> sous-périosté, thrombophlébite) en cas de gravité ou de mauvaise <span class=\"kw-clinique\">évolution</span> sous ATB</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Biologie</strong><br><em>(si suspicion IOA)</em></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-bio\">NFS</span></strong> · <strong><span class=\"kw-bio\">CRP</span></strong> (± <span class=\"kw-bio\">VS</span>)</li>\n                <li><strong>Prélèvements bactériologiques avant ATB</strong> :\n                  <ul>\n                    <li><span class=\"kw-chiffre\">2 hémocultures</span></li>\n                    <li>Si arthrite : <strong><span class=\"kw-ttt\">ponction</span> de liquide articulaire</strong> au bloc opératoire sous AG</li>\n                    <li>Si <span class=\"kw-clinique\">abcès</span> sous-périosté : <strong>pus</strong> au bloc</li>\n                  </ul>\n                </li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Une <em>RX normale n’élimine pas une ostéomyélite aiguë</em> à la phase précoce — <span class=\"kw-clinique\">les</span> signes radiologiques sont retardés de plusieurs jours. La biologie + l’<span class=\"kw-imagerie\">IRM</span> sont la clé.\n      </div>","frequence":1},{"id":"54-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître l’orientation diagnostique avec arbre décisionnel","contenu":"<p>L’<span class=\"kw-def\">orientation diagnostique</span> repose sur <strong>3 axes</strong> : (1) présence ou non de <em><span class=\"kw-clinique\">fièvre</span></em>, (2) <em>âge</em> de l’enfant, (3) <em>caractéristiques cliniques</em> de la boiterie.</p>\n\n      <h4>Bilan paraclinique minimal commun</h4>\n\n      <ul>\n        <li><strong>Biologie</strong> : <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">VS</span>, <span class=\"kw-bio\">CRP</span></li>\n        <li><strong>Imagerie</strong> : RX face/profil centrées sur la zone douloureuse + <span class=\"kw-imagerie\">échographie</span></li>\n        <li>Si forme fébrile : <strong><span class=\"kw-bio\">hémocultures</span> + prélèvements au bloc opératoire</strong> sous AG</li>\n      </ul>\n\n      <h4>Orientation selon le contexte</h4>\n\n      <table >\n        <thead>\n          <tr><th>Contexte</th><th>Diagnostics à évoquer</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Si fièvre</span></strong></td>\n            <td>\n              <strong>Boiterie fébrile = infection ostéo-articulaire jusqu’à preuve du contraire</strong> 🔥 (cf. <em>obj-1</em>)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>&lt;<span class=\"kw-chiffre\"> 3 ans</span></strong></td>\n            <td>\n              <ul>\n                <li><strong>Luxation <span class=\"kw-etio\">congénitale</span> de la hanche</strong> (limitation nette de l’abduction, échec de <span class=\"kw-def\">dépistage</span>)</li>\n                <li><strong>Fracture sous-périostée du tibia</strong> (fracture « en cheveu »)</li>\n                <li>Causes mécaniques : chaussures inadaptées, corps étranger plantaire</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-chiffre\">3-8 ans</span></strong></td>\n            <td>\n              <ul>\n                <li><strong>Synovite aiguë transitoire</strong> (« rhume de la hanche ») = diagnostic d’élimination</li>\n                <li><strong>Ostéochondrite primitive de hanche</strong> (Legg-Calvé-Perthes)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>&gt;<span class=\"kw-chiffre\"> 10 ans</span></strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-alerte\">Épiphysiolyse fémorale supérieure</span></strong></li>\n                <li><strong>Ostéochondrite du genou</strong> (ou ostéochondrite disséquante, adolescent)</li>\n                <li><strong>Apophysites de croissance</strong> (Osgood-Schlatter, Sever, Scheuerman)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Tout âge</strong></td>\n            <td>\n              <ul>\n                <li><strong>Tumeurs osseuses</strong> (bénignes ou malignes — membres ou rachis)</li>\n                <li><strong>Localisations osseuses des hémopathies malignes</strong> (<em>bandes claires métaphysaires en RX → LA</em>)</li>\n                <li><strong>Rhumatismes infantiles</strong> (arthrites juvéniles idiopathiques)</li>\n                <li><strong>Malformations congénitales</strong> (inégalité de longueur MI <span class=\"kw-chiffre\">&gt; 3-5 cm</span>)</li>\n                <li><strong>Pathologies neuromusculaires</strong> : myopathie, amyotrophie spinale, <span class=\"kw-clinique\">hémiplégie</span> cérébrale infantile, tumeur de la moelle</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> L’<em>âge de l’enfant</em> oriente directement <span class=\"kw-clinique\">les</span> hypothèses diagnostiques. <strong>Avant <span class=\"kw-chiffre\">3 ans</span></strong> → penser fracture en cheveu + luxation <span class=\"kw-etio\">congénitale</span>. <strong><span class=\"kw-chiffre\">3-8 ans</span></strong> → synovite ± Perthes. <strong>&gt;<span class=\"kw-chiffre\"> 10 ans</span></strong> → EFS jusqu’à preuve du contraire.\n      </div>","frequence":2},{"id":"54-6","rang":"A","rubrique":"Diagnostic positif","titre":"Infection ostéo-articulaire : connaître les arguments diagnostiques","contenu":"<p>L’<span class=\"kw-etio\">infection ostéo-articulaire</span> (IOA) regroupe l’<strong>ostéomyélite aiguë</strong> (atteinte osseuse) et l’<strong>arthrite septique</strong> (atteinte articulaire). Diagnostic à évoquer systématiquement devant toute boiterie fébrile de l’enfant.</p>\n\n      <h4>Arguments cliniques</h4>\n\n      <ul>\n        <li><span class=\"kw-clinique\">Fièvre</span> (± altération de l’état général)</li>\n        <li><strong>Impotence fonctionnelle</strong> : refus d’appui, boiterie d’esquive franche</li>\n        <li>Si <em>arthrite septique</em> : articulation chaude, douloureuse, position <span class=\"kw-ttt\">antalgique</span>, mobilisation impossible</li>\n        <li>Si <em>ostéomyélite</em> : douleur métaphysaire, palpation très douloureuse, ± <span class=\"kw-clinique\">œdème</span> localisé</li>\n        <li>Porte d’entrée : plaie, varicelle surinfectée, infection ORL récente</li>\n      </ul>\n\n      <h4>Arguments paracliniques</h4>\n\n      <table >\n        <thead>\n          <tr><th>Axe</th><th>Résultats évocateurs</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Biologie</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-bio\">NFS</span></strong> : hyperleucocytose à PNN</li>\n                <li><strong><span class=\"kw-bio\">CRP</span> ↗</strong> (marqueur le plus sensible) ± <strong><span class=\"kw-bio\">VS</span> ↗</strong></li>\n                <li><strong><span class=\"kw-bio\">Hémocultures</span> ×2</strong> avant ATB : souvent positives</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Imagerie</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-imagerie\">RX</span> : <em>normale</em> au début ; signes radiologiques retardés (déminéralisation, appositions périostées, géodes après plusieurs jours)</li>\n                <li><span class=\"kw-imagerie\">Échographie</span> : épaississement des parties molles, <span class=\"kw-clinique\">abcès</span> sous-périosté, épanchement articulaire (arthrite)</li>\n                <li><span class=\"kw-imagerie\">IRM</span> : examen de choix pour le <span class=\"kw-def\">diagnostic précoce</span> d’ostéomyélite et la recherche de complications (<span class=\"kw-clinique\">abcès</span>, thrombophlébite associée)</li>\n                <li><span class=\"kw-imagerie\">Scintigraphie</span> : si zone douloureuse difficile à localiser (jeune enfant)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Prélèvements bactériologiques</strong></td>\n            <td>\n              Indispensables, à effectuer <strong>avant toute <span class=\"kw-ttt\">antibiothérapie</span></strong> :\n              <ul>\n                <li><strong><span class=\"kw-bio\">Hémocultures</span></strong> (×2)</li>\n                <li><strong><span class=\"kw-ttt\">Ponction</span> articulaire</strong> au bloc sous AG si arthrite : analyse cytobactériologique du liquide</li>\n                <li><strong>Prélèvement du pus</strong> d’un <span class=\"kw-clinique\">abcès</span> sous-périosté au bloc</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Une <em>RX normale n’élimine pas une ostéomyélite</em> à la phase précoce. La <strong><span class=\"kw-bio\">CRP</span> + <span class=\"kw-imagerie\">IRM</span></strong> sont <span class=\"kw-clinique\">les</span> examens-clés du <span class=\"kw-def\">diagnostic précoce</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 156 — Infections ostéo-articulaires · 158 — <span class=\"kw-etio\">Sepsis</span> · 147 — <span class=\"kw-clinique\">Fièvre</span> aiguë chez l’enfant</em></p>","frequence":0},{"id":"54-7","rang":"B","rubrique":"Etiologies","titre":"Connaître les étiologies d’une boiterie non fébrile selon l’âge","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">étiologies non fébriles</span> sont stratifiées par <strong>tranche d’âge</strong>, avec quelques causes communes à tout âge (tumeurs, hémopathies, AJI, malformations, pathologies neuromusculaires).</p>\n\n      <h4>Étiologies par tranche d’âge</h4>\n\n      <div class=\"atlas-rubrique-card\" style=\"border-left: 3px solid var(--spe-pediatrie); padding: 12px 16px; margin: 12px 0;\">\n        <h4 style=\"margin-top: 0;\">Fracture sous-périostée du tibia (« en cheveu »)</h4>\n        <ul>\n          <li><strong>Âge</strong> : <span class=\"kw-chiffre\">&lt; 3 ans</span></li>\n          <li><strong>Cause</strong> : traumatisme <em>bénin</em> par torsion du membre, souvent passé inaperçu (chute de sa hauteur, pied pris entre <span class=\"kw-clinique\">les</span> barreaux du lit). Le périoste, très solide à cet âge, ne se déchire pas et assure la tenue mécanique de l’os ⭐</li>\n          <li><strong>Particularité</strong> : <em>seule fracture de jambe compatible avec l’appui et la marche</em></li>\n          <li><strong>Diagnostic radiologique</strong> :\n            <ul>\n              <li>Trait de fracture <strong>oblique ou en spire, fin à peine visible</strong> (image en « cheveu »)</li>\n              <li>Cal osseux observé <span class=\"kw-chiffre\">15 jours</span> plus tard (RX éventuellement répétée ou <span class=\"kw-imagerie\">scintigraphie</span>)</li>\n            </ul>\n          </li>\n          <li><strong>PEC</strong> : <strong>immobilisation plâtrée <span class=\"kw-ttt\">antalgique</span> <span class=\"kw-chiffre\">3-4 semaines</span></strong></li>\n        </ul>\n      </div>\n\n      <div class=\"atlas-rubrique-card\" style=\"border-left: 3px solid var(--spe-pediatrie); padding: 12px 16px; margin: 12px 0;\">\n        <h4 style=\"margin-top: 0;\">Synovite aiguë transitoire (« rhume de la hanche »)</h4>\n        <ul>\n          <li><strong>Âge</strong> : <span class=\"kw-chiffre\">3-8 ans</span>, plutôt chez le garçon</li>\n          <li><strong>Cause</strong> : arthrite réactionnelle post-<span class=\"kw-etio\">virale</span> (ORL ou intestinale) — période hivernale/printemps. <em>Pas de traumatisme</em></li>\n          <li><strong>Clinique</strong> :\n            <ul>\n              <li>Boiterie aiguë <strong>non fébrile</strong>, d’apparition <em>brutale, observée au réveil</em></li>\n              <li>Signes généraux : apyrétique (fébricule possible)</li>\n              <li>Topographie : douleur inguinale, fessière ou <em>projetée au genou</em></li>\n              <li>Intensité : rarement intense</li>\n              <li>Examen : limitation de la <strong>rotation interne et de l’abduction</strong> de hanche</li>\n            </ul>\n          </li>\n          <li><strong><span class=\"kw-alerte\">Drapeaux rouges</span> 🚩</strong> : apparition de <span class=\"kw-clinique\">fièvre</span>, aggravation, persistance &gt;<span class=\"kw-chiffre\"> 10 jours</span></li>\n          <li><strong>Paraclinique</strong> :\n            <ul>\n              <li>RX bassin face + hanche profil : <strong>normales</strong> ou épanchement</li>\n              <li>Écho de hanche : <strong>épanchement intra-articulaire</strong></li>\n              <li>Biologie : <em>pas de <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">infectieux</span></span> <span class=\"kw-ttt\">biologique</span></em> (<span class=\"kw-bio\">CRP</span> modérément ↗ possible)</li>\n              <li><span class=\"kw-ttt\">Ponction</span> articulaire uniquement si doute avec arthrite septique : liquide <span class=\"kw-etio\">inflammatoire</span> <strong>stérile</strong></li>\n            </ul>\n          </li>\n          <li><strong>PEC</strong> : mise en décharge, <span class=\"kw-ttt\">AINS</span>, ± traction axiale si douleurs importantes</li>\n          <li><strong><span class=\"kw-clinique\">Évolution</span></strong> : favorable en <span class=\"kw-chiffre\">5-10 jours</span>. <strong>RX de contrôle à 45 j /<span class=\"kw-chiffre\"> 2 mois</span></strong> pour dépister une ostéochondrite primitive de hanche débutante</li>\n        </ul>\n      </div>\n\n      <div class=\"atlas-rubrique-card\" style=\"border-left: 3px solid var(--spe-pediatrie); padding: 12px 16px; margin: 12px 0;\">\n        <h4 style=\"margin-top: 0;\">Ostéochondrite primitive de hanche — maladie de Legg-Calvé-Perthes</h4>\n        <ul>\n          <li><strong>Définition</strong> : <span class=\"kw-clinique\">nécrose</span> <span class=\"kw-etio\">ischémique</span> aseptique de l’épiphyse fémorale supérieure, d’origine inconnue, survenant pendant la croissance</li>\n          <li><strong><span class=\"kw-def\">Terrain</span></strong> : <span class=\"kw-chiffre\">3-9 ans</span>, <strong>garçon</strong> dans <span class=\"kw-chiffre\">80 %</span> des cas</li>\n          <li><strong><span class=\"kw-clinique\">Évolution</span> naturelle en 2 phases</strong> :\n            <ol>\n              <li><em><span class=\"kw-clinique\">Nécrose</span></em> : densification du noyau → <strong>fragmentation</strong> → déformation céphalique → ré-ossification</li>\n              <li><em>Séquelles</em> : <strong>coxa plana</strong> (forme aplatie) → arthrose secondaire ⚠️</li>\n            </ol>\n          </li>\n          <li><strong>Clinique</strong> :\n            <ul>\n              <li>Installation <em>insidieuse</em> (<span class=\"kw-bio\">vs</span> brutale dans la synovite)</li>\n              <li>État général conservé</li>\n              <li>Douleur : pli de l’aine, cuisse, voire <em>projetée au genou</em>, <strong>horaire mécanique</strong> (effort, fin de journée)</li>\n              <li>Ni permanente, ni toujours douloureuse → <em>diagnostic souvent retardé</em></li>\n              <li>Limitation de la <strong>rotation interne et de l’abduction</strong> + <strong>amyotrophie quadricipitale</strong></li>\n            </ul>\n          </li>\n          <li><strong>Biologie</strong> : <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">VS</span>, <span class=\"kw-bio\">CRP</span> <strong>normales</strong></li>\n          <li><strong>RX</strong> : initialement normales puis <em>3 phases</em> :\n            <ol>\n              <li><span class=\"kw-radio\">Condensation</span> : aplatissement du noyau, élargissement interligne</li>\n              <li>Fragmentation : fracture « en coup d’ongle » sous-chondral</li>\n              <li>Reconstruction : coxa plana, coxa magna séquellaires</li>\n            </ol>\n          </li>\n          <li><strong>Autres imageries</strong> :\n            <ul>\n              <li><span class=\"kw-imagerie\">Scintigraphie</span> : <em><span class=\"kw-radio\">hypofixation lacunaire</span></em> précoce</li>\n              <li><span class=\"kw-imagerie\">IRM</span> : <strong>hypoT1, hyperT2</strong></li>\n            </ul>\n          </li>\n          <li><strong><span class=\"kw-clinique\">Évolution</span></strong> : guérison spontanée en <span class=\"kw-chiffre\">18-24 mois</span> avec séquelles morphologiques ± graves. Facteurs de mauvais <span class=\"kw-def\">pronostic</span> : âge &gt;<span class=\"kw-chiffre\"> 6 ans</span>, <span class=\"kw-etio\">obésité</span>, excentration/déformation</li>\n          <li><strong>Traitement</strong> : avis orthopédique pédiatrique\n            <ul>\n              <li>Orthopédique : mise en décharge prolongée (± traction axiale, plâtre en abduction)</li>\n              <li>Chirurgical si diagnostic tardif (<em>ostéotomie de recentrage</em>)</li>\n            </ul>\n          </li>\n        </ul>\n      </div>\n\n      <div class=\"atlas-rubrique-card\" style=\"border-left: 3px solid var(--spe-urgences); padding: 12px 16px; margin: 12px 0;\">\n        <h4 style=\"margin-top: 0;\"><span class=\"kw-alerte\">Épiphysiolyse fémorale supérieure (EFS)</span></h4>\n        <ul>\n          <li><strong>Définition</strong> : maladie du cartilage de croissance → glissement de l’épiphyse fémorale supérieure sur la métaphyse, vers l’arrière et le bas</li>\n          <li><strong><span class=\"kw-def\">Terrain</span></strong> : <span class=\"kw-chiffre\">10-15 ans</span> (principale cause de boiterie de hanche prépubertaire/pubertaire), <strong>garçon</strong> (2,<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>5</span> G</span> / 1 F)</li>\n          <li><strong>FDR</strong> :\n            <ul>\n              <li><strong>Surcharge pondérale &gt;<span class=\"kw-chiffre\"> 50 %</span> des cas</strong>, prise rapide de poids = facteur déclenchant majeur</li>\n              <li><span class=\"kw-etio\">Hypothyroïdie</span>, déficit en GH, <span class=\"kw-etio\">IRC</span>, Klinefelter, hyperparathyroïdie, panhypopituitarisme</li>\n            </ul>\n          </li>\n          <li><strong>Clinique</strong> :\n            <ul>\n              <li>État général conservé</li>\n              <li>Douleur mécanique de hanche ou <em>projetée au genou</em>, boiterie permanente aggravée par l’effort</li>\n              <li>Membre en <strong>rotation latérale spontanée</strong></li>\n              <li>Limitation de la <strong>rotation interne et de l’abduction</strong></li>\n              <li><strong>Signe de Drehmann</strong> : la flexion de hanche entraîne une rotation externe + abduction automatique</li>\n            </ul>\n          </li>\n          <li><strong>Bilatéralité</strong> : <span class=\"kw-chiffre\">20 %</span> des cas</li>\n          <li><strong>2 formes cliniques</strong> :\n            <ul>\n              <li><em>Stable/chronique (<span class=\"kw-chiffre\">85 %</span>)</em> : appui possible</li>\n              <li><em>Instable/aiguë (<span class=\"kw-chiffre\">15 %</span>)</em> : hyperalgique, impotence fonctionnelle totale mimant une fracture (sans trauma)</li>\n            </ul>\n          </li>\n          <li><strong>Biologie</strong> : normale</li>\n          <li><strong>RX bassin + hanches face + faux profil (Lowenstein)</strong> :\n            <ul>\n              <li>Signe direct : <strong>bascule postérieure de la tête fémorale</strong> sur le profil</li>\n              <li>Signes indirects sur la face : cartilage de conjugaison irrégulier, feuilleté, élargi · ↘ hauteur de l’épiphyse</li>\n              <li><span class=\"kw-def\">Stade</span> tardif : <strong>ligne de Klein ne croise plus le pôle supérieur de l’épiphyse</strong></li>\n            </ul>\n          </li>\n          <li><strong>Traitement</strong> : <span class=\"kw-alerte\">urgence chirurgicale</span>, mise en décharge rapide jusqu’à l’intervention</li>\n        </ul>\n      </div>\n\n      <div class=\"atlas-rubrique-card\" style=\"border-left: 3px solid var(--spe-pediatrie); padding: 12px 16px; margin: 12px 0;\">\n        <h4 style=\"margin-top: 0;\">Apophysites de croissance</h4>\n        <ul>\n          <li><strong><span class=\"kw-def\">Terrain</span></strong> : <span class=\"kw-chiffre\">9-15 ans</span>, adolescent sportif</li>\n          <li><strong>Cause</strong> : répétition des gestes, sols durs, chaussures inadaptées, raideurs tendino-musculaires</li>\n          <li><strong>Localisations</strong> <span class=\"kw-clinique\">les</span> plus fréquentes :\n            <ul>\n              <li><strong>Tubérosité tibiale antérieure</strong> = <em>Osgood-Schlatter</em> (la plus fréquente)</li>\n              <li><strong>Calcanéum</strong> = <em>Sever</em></li>\n              <li><strong>Rachis</strong> = <em>Scheuerman</em></li>\n            </ul>\n          </li>\n          <li><strong>Douleur</strong> : apparition progressive ou brutale au sport, <strong>horaire mécanique</strong>, au site d’insertion tendineuse, réveillée par <em>palpation de l’apophyse</em> et <em>contraction musculaire contrariée</em></li>\n          <li><strong>RX</strong> : fragmentation et densification irrégulière du noyau d’ossification</li>\n          <li><strong>PEC</strong> : <strong>bénigne</strong> mais <span class=\"kw-clinique\">évolution</span> longue — repos sportif + physiothérapie <span class=\"kw-ttt\">antalgique</span></li>\n        </ul>\n      </div>\n\n      <h4>Pathologies à évoquer à tout âge</h4>\n\n      <table >\n        <thead>\n          <tr><th>Cadre</th><th>Caractéristiques à connaître</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Tumeurs osseuses</span></strong></td>\n            <td>\n              <ul>\n                <li><em>Bénignes</em> : rarement douloureuses, peuvent fragiliser l’os (fissure → boiterie)</li>\n                <li><em>Malignes</em> (sarcomes osseux) : <strong>horaire <span class=\"kw-etio\">inflammatoire</span> doit alerter</strong>, localisation préférentielle au genou (extrémité inf. fémur ou sup. tibia), diagnostic trop souvent retardé (faussement étiqueté tendinite/douleur de croissance)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Autres cancers</strong></td>\n            <td>\n              <ul>\n                <li><strong>Leucémie aiguë lymphoblastique</strong> : tout âge (bandes claires métaphysaires en RX)</li>\n                <li><strong>Neuroblastome métastatique</strong> : entre l’acquisition de la marche et <span class=\"kw-chiffre\">5 ans</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Malformations</strong></td>\n            <td>\n              Inégalité de longueur des MI = cause de boiterie seulement si <span class=\"kw-chiffre\">&gt; 3-5 cm</span>. <span class=\"kw-clinique\">Asymétrie</span> de hauteur des hanches de <span class=\"kw-chiffre\">1-2 cm</span> = <em>physiologique</em>. Radiomensuration des MI = seule mesure valable.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Neuro-musculaires</strong></td>\n            <td>\n              <ul>\n                <li>Myopathie, amyotrophie spinale : atteinte diffuse</li>\n                <li><span class=\"kw-clinique\">Hémiplégie</span> cérébrale infantile : perturbation ancienne, retard d’acquisition de la marche</li>\n                <li><strong>Tumeur de la moelle spinale</strong> : <span class=\"kw-clinique\">raideur du rachis doit alerter</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Rhumatismes infantiles</strong><br><em>(AJI)</em></td>\n            <td>\n              <ul>\n                <li>Âge de début <span class=\"kw-chiffre\">&lt; 16 ans</span> ; forme la plus fréquente : <strong>fille &lt;<span class=\"kw-chiffre\"> 6 ans</span></strong></li>\n                <li>Arthrite chronique d’une ou plusieurs grosses articulations (genoux, chevilles, rarement hanche)</li>\n                <li>Dérouillage matinal, réveils nocturnes</li>\n                <li>Articulation en flessum, amyotrophie homolatérale</li>\n                <li><strong>Absence de <span class=\"kw-clinique\">fièvre</span></strong>, <span class=\"kw-bio\">syndrome inflammatoire</span> souvent <em>modéré voire absent</em></li>\n                <li>Particularité : uvéites froides associées, AC anti-nucléaires</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 55 — Développement psychomoteur de l’enfant · 196 — <span class=\"kw-etio\">Polyarthrite rhumatoïde</span> et arthrite juvénile idiopathique</em></p>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/toddler-fracture","label":"Radiopaedia : Toddler fracture"},{"href":"https://radiopaedia.org/articles/transient-synovitis-of-the-hip","label":"Radiopaedia : Synovite aiguë transitoire de hanche"},{"href":"https://radiopaedia.org/articles/perthes-disease","label":"Radiopaedia : Perthes disease (LCPE)"},{"href":"https://radiopaedia.org/articles/slipped-upper-femoral-epiphysis","label":"Radiopaedia : Épiphysiolyse fémorale supérieure (SUFE)"}]}],"astuces":[{"type":"info","titre":"Astuces & pièges et stratégie","contenu":"<p>Couches « Astuces de PU & Pièges » et « Stratégie & CAT » : à compléter après revue clinique.</p>"}],"strategie":{"urgence":"<p><strong>Boiterie fébrile <span class=\"q\">— IOA jusqu’à preuve du contraire</span></strong></p><p><span class=\"kw-ttt\">Prélèvements bactériologiques au bloc</span> (<span class=\"kw-ttt\">ponction</span> articulaire / pus) sous AG, puis <span class=\"kw-ttt\">antibiothérapie</span></p><ul><li>Bilan <span class=\"kw-ttt\">biologique</span> et imagerie <span class=\"kw-alerte\">en urgence</span></li><li><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span> (± <span class=\"kw-bio\">VS</span>) · <span class=\"kw-bio\">hémocultures</span> ×2 avant toute <span class=\"kw-ttt\">antibiothérapie</span></li><li><span class=\"kw-imagerie\">RX</span> face + profil centrées + <span class=\"kw-imagerie\">échographie</span> articulaire</li></ul><p><strong>Épiphysiolyse fémorale supérieure <span class=\"q\">— adolescent</span></strong></p><p><span class=\"kw-ttt\">Mise en décharge</span> immédiate (interdiction d’appui) jusqu’à l’intervention</p><ul><li><span class=\"kw-alerte\">Urgence chirurgicale</span> (<span class=\"kw-chiffre\">10-15 ans</span>, douleur de hanche ou projetée au genou)</li><li>Forme <span class=\"kw-alerte\">instable/aiguë</span> : hyperalgique, <span class=\"kw-clinique\">impotence fonctionnelle totale</span> mimant une fracture</li></ul>","hospit":"<p><strong>Ambulatoire :</strong> formes bénignes non fébriles — <span class=\"kw-def\">synovite aiguë transitoire</span> (<span class=\"kw-ttt\">repos</span>, <span class=\"kw-ttt\">AINS</span>) et <span class=\"kw-def\">apophysites de croissance</span> (<span class=\"kw-ttt\">repos sportif</span>).<br><strong><span class=\"kw-alerte\">Hospitalisation</span> :</strong> toute <span class=\"kw-alerte\">boiterie fébrile</span> / suspicion d’<span class=\"kw-def\">infection ostéo-articulaire</span> → bilan + <span class=\"kw-ttt\">prélèvements au bloc opératoire</span> sous AG.<br><strong><span class=\"kw-alerte\">Urgence</span> chirurgicale :</strong> <span class=\"kw-alerte\">épiphysiolyse fémorale supérieure</span> → mise en décharge rapide jusqu’à l’intervention.<br><strong>Avis orthopédique pédiatrique :</strong> <span class=\"kw-def\">ostéochondrite primitive de hanche</span> (Legg-Calvé-Perthes), <span class=\"kw-def\">luxation congénitale de hanche</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Boiterie fébrile</span> → infection ostéo-articulaire jusqu’à preuve du contraire</li><li><span class=\"kw-clinique\">Horaire inflammatoire</span> des douleurs (réveils nocturnes) → <span class=\"kw-alerte\">tumeur osseuse</span> / <span class=\"kw-alerte\">sarcome</span></li><li><span class=\"kw-imagerie\">Bandes claires métaphysaires</span> sur la RX → <span class=\"kw-alerte\">leucémie aiguë</span></li><li><span class=\"kw-clinique\">Raideur du rachis</span> / <span class=\"kw-clinique\">refus de la station assise</span> → <span class=\"kw-alerte\">tumeur de la moelle spinale</span></li><li><span class=\"kw-clinique\">Amyotrophie quadricipitale</span> = signe formel d’<span class=\"kw-clinique\">organicité</span> et d’ancienneté</li><li>EFS <span class=\"kw-alerte\">instable/aiguë</span> : <span class=\"kw-clinique\">impotence fonctionnelle totale</span> mimant une fracture (sans traumatisme)</li><li>Synovite : <span class=\"kw-alerte\">apparition d’une fièvre</span>, aggravation ou <span class=\"kw-chiffre\">persistance &gt; 10 jours</span> → réévaluer (arthrite septique ?)</li></ul>","principes":"<p><strong>Règle d’or :</strong> la <span class=\"kw-alerte\">boiterie fébrile</span> impose des <span class=\"kw-ttt\">prélèvements bactériologiques avant toute antibiothérapie</span> ; <span class=\"kw-clinique\">les</span> formes non fébriles relèvent d’un traitement <span class=\"kw-def\">orthopédique</span> adapté à l’étiologie et à l’âge.</p><p><strong>Infection ostéo-articulaire</strong></p><ul><li><span class=\"kw-bio\">Hémocultures</span> ×2 + <span class=\"kw-ttt\">ponction articulaire</span> / <span class=\"kw-ttt\">prélèvement de pus</span> au bloc sous AG</li><li><span class=\"kw-ttt\">Antibiothérapie</span> secondairement (après <span class=\"kw-clinique\">les</span> prélèvements)</li></ul><p><strong>Fracture sous-périostée du tibia <span class=\"q\">(« en cheveu »)</span></strong></p><ul><li>Seule fracture de jambe <span class=\"kw-clinique\">compatible avec l’appui</span> et la marche</li><li><span class=\"kw-ttt\">Immobilisation plâtrée antalgique</span> pendant <span class=\"kw-chiffre\">3-4 semaines</span></li></ul><p><strong>Synovite aiguë transitoire</strong></p><ul><li><span class=\"kw-ttt\">Mise en décharge</span> (repos, <span class=\"kw-ttt\">réduction</span> des sorties)</li><li><span class=\"kw-ttt\">AINS</span> (bon effet <span class=\"kw-ttt\">antalgique</span>) ± <span class=\"kw-ttt\">traction axiale</span> si douleurs importantes</li></ul><p><strong>Ostéochondrite primitive de hanche (Perthes)</strong></p><ul><li><span class=\"kw-ttt\">Avis orthopédique pédiatrique</span> : éviter la déformation de la tête fémorale</li><li>Orthopédique : <span class=\"kw-ttt\">mise en décharge prolongée</span> (± <span class=\"kw-ttt\">traction axiale</span>, <span class=\"kw-ttt\">plâtre en abduction</span>)</li><li>Chirurgical si diagnostic tardif (<span class=\"kw-ttt\">ostéotomie de recentrage</span>)</li></ul><p><strong>Épiphysiolyse fémorale supérieure</strong></p><ul><li><span class=\"kw-alerte\">Urgence chirurgicale</span> + <span class=\"kw-ttt\">mise en décharge</span> rapide jusqu’à l’intervention</li></ul><p><strong>Apophysites de croissance</strong></p><ul><li><span class=\"kw-def\">Pronostic</span> <strong>bénin</strong> (<span class=\"kw-clinique\">évolution</span> longue) : <span class=\"kw-ttt\">repos sportif</span> + <span class=\"kw-ttt\">physiothérapie antalgique</span></li></ul>","suivi":"<p><strong>Synovite transitoire :</strong> <span class=\"kw-clinique\">évolution</span> favorable en <span class=\"kw-chiffre\">5-10 jours</span> ; <span class=\"kw-imagerie\">RX de contrôle à 45 j / 2 mois</span> pour dépister une <span class=\"kw-def\">ostéochondrite primitive de hanche</span> débutante.<br><strong>Fracture « en cheveu » :</strong> <span class=\"kw-imagerie\">cal osseux</span> visible sur la RX <span class=\"kw-chiffre\">15 jours</span> plus tard (RX répétée ou <span class=\"kw-imagerie\">scintigraphie</span>).<br><strong>Maladie de Perthes :</strong> guérison spontanée en <span class=\"kw-chiffre\">18-24 mois</span> avec <span class=\"kw-alerte\">séquelles morphologiques</span> ± graves (<span class=\"kw-def\">coxa plana</span> → arthrose) ; mauvais <span class=\"kw-def\">pronostic</span> si âge <span class=\"kw-chiffre\">&gt; 6 ans</span>, <span class=\"kw-etio\">obésité</span>.<br><strong>EFS :</strong> surveiller la <span class=\"kw-clinique\">bilatéralité</span> (<span class=\"kw-chiffre\">20 %</span> des cas).</p>"},"liensGlobaux":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/urgences-reanimation-chirurgie-orthopedique/boiteries-infections-osteoarticulaires","label":"Collège Pédiatrie — Boiteries & infections ostéo-articulaires"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Boiterie de l’enfant — Anomalie récente et asymétrique de la marche — éliminer d’abord une cause urgente","detail":"<h4>CAT — boiterie de l’enfant — Orientation diagnostique : <span class=\"kw-clinique\">fièvre</span>, puis âge et caractéristiques de la boiterie</h4>","branches":[{"to":"t-ioa","label":"Fièvre / syndrome infectieux","color":"red"},{"to":"q-age","label":"Pas de fièvre — orienter selon l’âge","color":"amber"}]},{"id":"t-ioa","kind":"terminal","label":"Infection ostéo-articulaire jusqu’à preuve du contraire","color":"red","detail":"<h4>Règle</h4><ul><li>Toute <span class=\"kw-alerte\">boiterie fébrile</span> de l’enfant est une <span class=\"kw-alerte\">infection ostéo-articulaire jusqu’à preuve du contraire</span> — bilan en <span class=\"kw-alerte\">urgence</span>.</li></ul><h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Fièvre</span> ± <span class=\"kw-clinique\">AEG</span>, <span class=\"kw-clinique\">impotence fonctionnelle</span> (refus d’appui)</li><li>Arthrite septique : articulation chaude, douloureuse, mobilisation impossible</li><li>Ostéomyélite : <span class=\"kw-clinique\">douleur métaphysaire</span> exquise à la palpation</li><li>Porte d’entrée : plaie, varicelle surinfectée, infection ORL récente</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">NFS</span> (hyperleucocytose à PNN), <span class=\"kw-bio\">CRP</span> ↗ (± <span class=\"kw-bio\">VS</span>)</li><li><span class=\"kw-imagerie\">RX</span> souvent <strong>normale</strong> au début · <span class=\"kw-imagerie\">échographie</span> (épanchement, <span class=\"kw-clinique\">abcès</span> sous-périosté) · <span class=\"kw-imagerie\">IRM</span> = <span class=\"kw-def\">diagnostic précoce</span> d’ostéomyélite</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-bio\">Hémocultures</span> ×2 + <span class=\"kw-ttt\">ponction / pus au bloc</span> sous AG <strong>avant</strong> toute <span class=\"kw-ttt\">antibiothérapie</span></li><li><span class=\"kw-alerte\">Hospitalisation</span> en <span class=\"kw-alerte\">urgence</span></li></ul><h4>Renvoi</h4><ul><li>Item 156 (infections ostéo-articulaires) · Item 158 (<span class=\"kw-alerte\">sepsis</span>) · Item 147 (<span class=\"kw-clinique\">fièvre</span> aiguë de l’enfant)</li></ul>"},{"id":"q-age","kind":"decision","label":"Âge de l’enfant ? — Chaque tranche d’âge a ses étiologies de prédilection","branches":[{"to":"t-jeune","label":"< 3 ans","color":"amber"},{"to":"q-3-8","label":"3-8 ans","color":"green"},{"to":"t-efs","label":"> 10 ans (prépubère / pubère)","color":"red"},{"to":"t-toutage","label":"Tout âge — signe d’alerte (horaire inflammatoire, douleur rachidienne)","color":"red"}]},{"id":"t-jeune","kind":"terminal","label":"Avant 3 ans : fracture « en cheveu » & luxation congénitale","color":"amber","detail":"<h4>Fracture sous-périostée du tibia (« en cheveu »)</h4><ul><li>Traumatisme <strong>bénin</strong> par torsion, souvent passé inaperçu</li><li><span class=\"kw-clinique\">Seule fracture de jambe compatible avec l’appui</span> et la marche</li><li><span class=\"kw-imagerie\">RX</span> : trait oblique/spiroïde fin « en cheveu » ; <span class=\"kw-imagerie\">cal osseux</span> à <span class=\"kw-chiffre\">15 jours</span></li><li><span class=\"kw-ttt\">Immobilisation plâtrée antalgique</span> <span class=\"kw-chiffre\">3-4 semaines</span></li></ul><h4>Luxation <span class=\"kw-etio\">congénitale</span> de hanche</h4><ul><li><span class=\"kw-clinique\">Limitation nette de l’abduction</span> — conséquence d’un échec du <span class=\"kw-def\">dépistage</span> ; <span class=\"kw-ttt\">avis orthopédique</span>.</li></ul><h4>Autres</h4><ul><li>Causes mécaniques : chaussures inadaptées, corps étranger plantaire.</li></ul>"},{"id":"q-3-8","kind":"decision","label":"3-8 ans : mode d’installation de la boiterie ? — Brutale au réveil (synovite) vs insidieuse, horaire mécanique (Perthes)","branches":[{"to":"t-synovite","label":"Brutale, au réveil, apyrétique","color":"green"},{"to":"t-perthes","label":"Insidieuse, horaire mécanique, traînante","color":"amber"}]},{"id":"t-synovite","kind":"terminal","label":"Synovite aiguë transitoire (« rhume de la hanche »)","color":"green","detail":"<h4><span class=\"kw-def\">Terrain</span> & cause</h4><ul><li><span class=\"kw-chiffre\">3-8 ans</span>, garçon ++ ; <span class=\"kw-etio\">arthrite réactionnelle post-virale</span> (ORL/intestinale), période hivernale ; <strong>diagnostic d’élimination</strong>.</li></ul><h4>Clinique</h4><ul><li>Boiterie <span class=\"kw-clinique\">brutale, non fébrile</span>, observée au réveil</li><li>Douleur inguinale, fessière ou <span class=\"kw-clinique\">projetée au genou</span></li><li><span class=\"kw-clinique\">Limitation de la rotation interne et de l’abduction</span> de hanche</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">RX</span> bassin face + hanche profil : normales ou épanchement</li><li><span class=\"kw-imagerie\">Échographie</span> : <span class=\"kw-clinique\">épanchement intra-articulaire</span></li><li><span class=\"kw-bio\">Biologie</span> : pas de <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">infectieux</span></span> (<span class=\"kw-bio\">CRP</span> modérément ↗ possible)</li></ul><h4>PEC & <span class=\"kw-def\">suivi</span></h4><ul><li><span class=\"kw-ttt\">Mise en décharge</span> + <span class=\"kw-ttt\">AINS</span> ± <span class=\"kw-ttt\">traction axiale</span> si douleurs importantes</li><li>Favorable en <span class=\"kw-chiffre\">5-10 jours</span> ; <span class=\"kw-imagerie\">RX de contrôle à 45 j / 2 mois</span> (dépister un Perthes débutant)</li></ul><h4><span class=\"kw-alerte\">Red flags</span></h4><ul><li><span class=\"kw-alerte\">Fièvre</span>, aggravation, <span class=\"kw-chiffre\">persistance &gt; 10 jours</span> → réévaluer (arthrite septique).</li></ul>"},{"id":"t-perthes","kind":"terminal","label":"Ostéochondrite primitive de hanche (Legg-Calvé-Perthes)","color":"amber","detail":"<h4>Définition & <span class=\"kw-def\">terrain</span></h4><ul><li><span class=\"kw-etio\">Nécrose ischémique aseptique</span> de l’épiphyse fémorale supérieure ; <span class=\"kw-chiffre\">3-9 ans</span>, garçon (<span class=\"kw-chiffre\">80 %</span>).</li></ul><h4>Clinique</h4><ul><li>Installation <span class=\"kw-clinique\">insidieuse</span>, état général conservé</li><li>Douleur du pli de l’aine / <span class=\"kw-clinique\">projetée au genou</span>, <span class=\"kw-clinique\">horaire mécanique</span></li><li><span class=\"kw-clinique\">Limitation rotation interne / abduction</span> + <span class=\"kw-clinique\">amyotrophie quadricipitale</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">VS</span>, <span class=\"kw-bio\">CRP</span> normales</li><li><span class=\"kw-imagerie\">RX</span> : condensation → fragmentation → <span class=\"kw-imagerie\">coxa plana</span> ; <span class=\"kw-imagerie\">IRM</span> hypoT1/hyperT2, <span class=\"kw-imagerie\">scintigraphie</span> hypofixation précoce</li></ul><h4>PEC & <span class=\"kw-def\">pronostic</span></h4><ul><li><span class=\"kw-ttt\">Avis orthopédique pédiatrique</span> : <span class=\"kw-ttt\">mise en décharge prolongée</span> (± <span class=\"kw-ttt\">plâtre en abduction</span>), <span class=\"kw-ttt\">ostéotomie</span> si diagnostic tardif</li><li>Guérison en <span class=\"kw-chiffre\">18-24 mois</span> avec <span class=\"kw-alerte\">séquelles</span> ± graves (arthrose) ; mauvais <span class=\"kw-def\">pronostic</span> si âge <span class=\"kw-chiffre\">&gt; 6 ans</span>, <span class=\"kw-etio\">obésité</span></li></ul>"},{"id":"t-efs","kind":"terminal","label":"Épiphysiolyse fémorale supérieure (EFS) jusqu’à preuve du contraire","color":"red","detail":"<h4><span class=\"kw-def\">Terrain</span></h4><ul><li><span class=\"kw-chiffre\">10-15 ans</span>, garçon (2,5 / 1) ; <span class=\"kw-etio\">surcharge pondérale</span> &gt;<span class=\"kw-chiffre\"> 50 %</span> des cas (FDR : <span class=\"kw-etio\">hypothyroïdie</span>, déficit en GH, <span class=\"kw-etio\">insuffisance rénale chronique</span>).</li></ul><h4>Clinique</h4><ul><li>État général conservé ; douleur mécanique de hanche ou <span class=\"kw-clinique\">projetée au genou</span></li><li>Membre en <span class=\"kw-clinique\">rotation latérale spontanée</span>, <span class=\"kw-clinique\">limitation rotation interne / abduction</span></li><li><span class=\"kw-clinique\">Signe de Drehmann</span> ; forme <span class=\"kw-alerte\">instable/aiguë</span> (<span class=\"kw-chiffre\">15 %</span>) hyperalgique mimant une fracture</li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">RX</span> bassin + hanches face + faux profil (Lowenstein) : <span class=\"kw-imagerie\">bascule postérieure de la tête fémorale</span> ; <span class=\"kw-imagerie\">ligne de Klein</span> ne croise plus l’épiphyse.</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Urgence chirurgicale</span> + <span class=\"kw-ttt\">mise en décharge</span> rapide jusqu’à l’intervention</li><li>Surveiller la <span class=\"kw-clinique\">bilatéralité</span> (<span class=\"kw-chiffre\">20 %</span> des cas)</li></ul><h4>Autres causes <span class=\"kw-chiffre\">> 10 ans</span></h4><ul><li>Ostéochondrite du genou (disséquante) ; <span class=\"kw-def\">apophysites de croissance</span> (Osgood-Schlatter, Sever, Scheuerman) — bénignes, <span class=\"kw-ttt\">repos sportif</span>.</li></ul>"},{"id":"t-toutage","kind":"terminal","label":"Tout âge — éliminer une cause grave","color":"red","detail":"<h4>Tumeurs osseuses</h4><ul><li>Bénignes (fragilisation osseuse) ou malignes (<span class=\"kw-etio\">sarcomes</span>) : <span class=\"kw-clinique\">horaire inflammatoire</span> doit alerter, localisation préférentielle au genou ; diagnostic souvent retardé.</li></ul><h4>Hémopathies</h4><ul><li><span class=\"kw-etio\">Leucémie aiguë lymphoblastique</span> (<span class=\"kw-imagerie\">bandes claires métaphysaires</span> en RX) ; <span class=\"kw-etio\">neuroblastome métastatique</span> (acquisition de la marche →<span class=\"kw-chiffre\"> 5 ans</span>).</li></ul><h4>Rhumatismes</h4><ul><li><span class=\"kw-def\">Arthrite juvénile idiopathique</span> : <span class=\"kw-clinique\">absence de fièvre</span>, <span class=\"kw-bio\">syndrome inflammatoire</span> modéré voire absent ; arthrite chronique, dérouillage matinal, uvéites froides.</li></ul><h4>Neuromusculaires & malformations</h4><ul><li><span class=\"kw-etio\">Myopathie</span>, amyotrophie spinale, <span class=\"kw-clinique\">hémiplégie cérébrale infantile</span>, tumeur de la moelle (<span class=\"kw-clinique\">raideur du rachis</span>)</li><li>Inégalité de longueur des membres inférieurs <span class=\"kw-chiffre\">&gt; 3-5 cm</span></li></ul><h4>Renvoi</h4><ul><li>Item 196 (arthrite juvénile idiopathique)</li></ul>"}]},"cards":[{"i":"2dbdfc09e2f9","n":54,"o":"54-1","u":"Définition","t":"Connaître la définition de la boiterie de l’enfant","q":"Quelle est la définition générale de la boiterie chez l'enfant ?","a":"<p>La boiterie de l'enfant correspond à une <strong>anomalie récente de la marche</strong>, qui devient <strong>asymétrique</strong>. Elle doit être distinguée des troubles de la démarche anciens ou présents depuis l'acquisition de la marche.</p>"},{"i":"3ce40632279e","n":54,"o":"54-1","u":"Définition","t":"Connaître la définition de la boiterie de l’enfant","q":"Comment se manifeste une boiterie d'esquive (ou antalgique) chez l'enfant et quelle en est la cause principale ?","a":"<p>La boiterie d'esquive se manifeste par le fait que l'enfant <strong>évite ou raccourcit le temps d'appui</strong> du côté pathologique et déporte le poids de son corps du côté opposé. Cette boiterie est principalement causée par une <strong>douleur du membre inférieur</strong>.</p>"},{"i":"d3f43c13e566","n":54,"o":"54-1","u":"Définition","t":"Connaître la définition de la boiterie de l’enfant","q":"Comment reconnaître une boiterie d'épaule (ou d'équilibration, ou de Trendelenburg) chez l'enfant et que cela indique-t-il ?","a":"<p>Une boiterie d'épaule se caractérise par un <strong>basculement des épaules</strong> à chaque appui du côté pathologique. Cela indique une <strong>insuffisance des muscles fessiers</strong>, souvent associée à une pathologie chronique de la hanche.</p>"},{"i":"712af9d370e2","n":54,"o":"54-2","u":"Définition","t":"Boiterie fébrile : toujours rechercher une infection ostéoarticulaire","q":"Quels sont les examens complémentaires à réaliser en urgence devant une boiterie fébrile chez l'enfant ?","a":"<ul><li><strong>Biologiques</strong> : NFS, CRP (± VS), et 2 paires d'hémocultures <strong>avant toute antibiothérapie</strong>.</li><li><strong>Imagerie</strong> : radiographies de face et profil centrées sur la zone douloureuse, et échographie articulaire (pour rechercher un épanchement ou un abcès sous-périosté).</li><li><strong>Prélèvements bactériologiques</strong> : hémocultures (x2) ; ponction articulaire si arthrite et prélèvement de pus en cas d'abcès sous-périosté.</li></ul>"},{"i":"f00532039723","n":54,"o":"54-2","u":"Définition","t":"Boiterie fébrile : toujours rechercher une infection ostéoarticulaire","q":"Quels diagnostics différentiels doivent être éliminés face à une boiterie chez l'enfant, notamment en présence de fièvre ?","a":"<ul><li>La <strong>synovite aiguë transitoire</strong> (« rhume de la hanche ») : souvent <strong>non fébrile</strong> et diagnostic d'élimination.</li><li>L'<strong>arthrite juvénile idiopathique</strong> : se caractérise par l'<strong>absence de fièvre</strong> et un syndrome inflammatoire souvent modéré voire absent.</li><li>Les <strong>pathologies tumorales</strong> : l'horaire inflammatoire des douleurs doit alerter.</li></ul>"},{"i":"f50b810e3957","n":54,"o":"54-2","u":"Définition","t":"Boiterie fébrile : toujours rechercher une infection ostéoarticulaire","q":"Quelle est l'attitude cruciale devant toute boiterie fébrile chez l'enfant ?","a":"<p>Toute boiterie fébrile chez l'enfant doit être considérée comme une <strong>infection ostéo-articulaire</strong> jusqu'à preuve du contraire.</p>"},{"i":"5a7e5613b5ed","n":54,"o":"54-3","u":"Diagnostic positif","t":"Boiterie de l’enfant : connaître les éléments de l’interrogatoire et de l’examen clinique","q":"Comment doit être mené l'examen clinique initial d'un enfant présentant une boiterie ?","a":"<p>L'examen clinique doit être <strong>systématique, déchaussé et dévêtu</strong> chez l'enfant. Il commence par l'<strong>observation de la boiterie</strong> (esquive vs équilibration), suivie d'une <strong>inspection</strong> (attitude vicieuse, lésions cutanées, amyotrophie quadricipitale). Une <strong>palpation méthodique</strong> doit ensuite être réalisée du distal vers le proximal, puis une <strong>mobilisation articulaire</strong> de toutes les articulations, en comparant avec le côté opposé.</p>"},{"i":"6f90da694e6a","n":54,"o":"54-3","u":"Diagnostic positif","t":"Boiterie de l’enfant : connaître les éléments de l’interrogatoire et de l’examen clinique","q":"Quels sont les trois pièges classiques à avoir en tête lors de l'interrogatoire d'une boiterie chez l'enfant ?","a":"<p>Les trois pièges classiques lors de l'interrogatoire sont :</p><ul><li>Des <strong>douleurs du genou</strong> secondaires à une atteinte de la hanche (douleurs projetées).</li><li>Un <strong>épisode traumatique antérieur</strong> (banal chez l'enfant) faussement évoqué comme cause unique.</li><li>Un <strong>psoïtis</strong>, qui peut être la cause de difficultés à la marche (par exemple, dans le cadre d'une appendicite aiguë).</li></ul>"},{"i":"775e5174d8f9","n":54,"o":"54-3","u":"Diagnostic positif","t":"Boiterie de l’enfant : connaître les éléments de l’interrogatoire et de l’examen clinique","q":"Quels sont les éléments clés à rechercher lors de l'interrogatoire devant une boiterie chez l'enfant ?","a":"<p>Lors de l'interrogatoire, il faut rechercher :</p><ul><li>Le <strong>terrain</strong> : âge (pathologies spécifiques), antécédents médicaux (prématurité, drépanocytose, obésité) et développement psychomoteur.</li><li>Les <strong>circonstances d'apparition</strong> : contexte infectieux (fièvre, porte d'entrée cutanée, infection ORL), traumatisme récent ou présence d'un corps étranger.</li><li>La <strong>symptomatologie</strong> : caractéristiques de la boiterie (brutale ou progressive, ancienneté, évolution, permanence), et si douleur, sa date d'apparition et sa localisation.</li></ul>"},{"i":"dcd176bca624","n":54,"o":"54-3","u":"Diagnostic positif","t":"Boiterie de l’enfant : connaître les éléments de l’interrogatoire et de l’examen clinique","q":"Hormis les membres inférieurs, quelles autres régions du corps doivent être examinées devant une boiterie chez l'enfant et pourquoi ?","a":"<p>Outre les membres inférieurs, il est impératif d'examiner :</p><ul><li>Le <strong>rachis</strong> : rechercher douleur à la palpation, raideur ou refus de la station assise (parfois seul signe d'atteinte rachidienne).</li><li>L'<strong>abdomen</strong> : par palpation, pour ne pas méconnaître une étiologie abdominale (ex: appendicite entraînant un psoïtis).</li><li>Un <strong>examen cutané général</strong> : recherche d'ecchymoses, de plaies ou de portes d'entrée infectieuses.</li><li>Un <strong>examen neurologique</strong> : pour détecter des troubles de la marche (équin), du tonus ou de la force musculaire.</li></ul><p>Il est important de se rappeler que les atteintes de hanche ne représentent pas la majorité des boiteries (< 40%).</p>"},{"i":"f49d2beacc89","n":54,"o":"54-3","u":"Diagnostic positif","t":"Boiterie de l’enfant : connaître les éléments de l’interrogatoire et de l’examen clinique","q":"Quels sont les éléments spécifiques à rechercher lors de la palpation et de la mobilisation articulaire chez un enfant qui boite ?","a":"<p>Lors de la palpation, il faut rechercher une douleur au niveau des <strong>diaphyses tibiales</strong> (fracture sous-périostée) et des <strong>métaphyses</strong> (douleur, chaleur, rougeur, tuméfaction). Lors de la mobilisation articulaire, on recherche une douleur provoquée ou un déficit d'amplitude. Une <strong>limitation de l'abduction et de la rotation interne</strong> est un signe clé de <strong>toute atteinte de la hanche</strong>.</p>"},{"i":"21c2a0313676","n":54,"o":"54-5","u":"Diagnostic positif","t":"Connaître l’orientation diagnostique avec arbre décisionnel","q":"Quel bilan paraclinique minimal commun est recommandé pour une boiterie chez l'enfant ?","a":"<p>Le bilan paraclinique minimal commun pour une boiterie chez l'enfant comprend :</p><ul><li><strong>Biologie</strong> : Numération Formule Sanguine (<strong>NFS</strong>), Vitesse de Sédimentation (<strong>VS</strong>), Protéine C Réactive (<strong>CRP</strong>).</li><li><strong>Imagerie</strong> : <strong>Radiographies face et profil</strong> centrées sur la zone douloureuse, et une <strong>échographie</strong>.</li><li>En cas de forme fébrile, des <strong>hémocultures</strong> et des prélèvements au bloc opératoire sous anesthésie générale sont indiqués.</li></ul>"},{"i":"2409a2fdd67a","n":54,"o":"54-5","u":"Diagnostic positif","t":"Connaître l’orientation diagnostique avec arbre décisionnel","q":"Quels diagnostics de boiterie évoquer chez l'enfant de 3 à 8 ans ?","a":"<p>Chez l'enfant de <strong>3 à 8 ans</strong> présentant une boiterie, il faut évoquer :</p><ul><li>La <strong>synovite aiguë transitoire</strong> (« rhume de la hanche »), qui est un diagnostic d'élimination.</li><li>L'<strong>ostéochondrite primitive de hanche</strong> (maladie de Legg-Calvé-Perthes).</li></ul>"},{"i":"50d2dffd14b7","n":54,"o":"54-5","u":"Diagnostic positif","t":"Connaître l’orientation diagnostique avec arbre décisionnel","q":"Quels diagnostics de boiterie chez l'enfant de moins de 3 ans doit-on évoquer en priorité ?","a":"<p>Chez l'enfant de <strong>moins de 3 ans</strong>, il faut évoquer en priorité :</p><ul><li>La <strong>luxation congénitale de la hanche</strong> (avec limitation nette de l'abduction ou échec de dépistage).</li><li>La <strong>fracture sous-périostée du tibia</strong> (fracture « en cheveu »).</li><li>Les <strong>causes mécaniques</strong> (chaussures inadaptées, corps étranger plantaire).</li></ul>"},{"i":"b9aa10c815b4","n":54,"o":"54-5","u":"Diagnostic positif","t":"Connaître l’orientation diagnostique avec arbre décisionnel","q":"Quels sont les trois axes principaux de l'orientation diagnostique d'une boiterie chez l'enfant ?","a":"<p>L'orientation diagnostique d'une boiterie chez l'enfant repose sur :</p><ul><li>La présence ou non de <strong>fièvre</strong>.</li><li>L'<strong>âge</strong> de l'enfant.</li><li>Les <strong>caractéristiques cliniques</strong> de la boiterie.</li></ul>"},{"i":"bdfe23a06b2e","n":54,"o":"54-5","u":"Diagnostic positif","t":"Connaître l’orientation diagnostique avec arbre décisionnel","q":"Quels diagnostics de boiterie évoquer chez l'enfant de plus de 10 ans ?","a":"<p>Chez l'enfant de <strong>plus de 10 ans</strong> présentant une boiterie, il faut évoquer :</p><ul><li>L'<strong>épiphysiolyse fémorale supérieure</strong> (EFS).</li><li>L'<strong>ostéochondrite du genou</strong> (ou ostéochondrite disséquante).</li><li>Les <strong>apophysites de croissance</strong> (maladie d'Osgood-Schlatter, de Sever, de Scheuermann).</li></ul>"},{"i":"eddc9b326279","n":54,"o":"54-5","u":"Diagnostic positif","t":"Connaître l’orientation diagnostique avec arbre décisionnel","q":"Quelle est l'orientation diagnostique devant une boiterie fébrile chez l'enfant ?","a":"<p>Devant une <strong>boiterie fébrile</strong> chez l'enfant, il faut considérer une <strong>infection ostéo-articulaire</strong> jusqu'à preuve du contraire.</p>"},{"i":"94a22f457cf5","n":54,"o":"54-6","u":"Diagnostic positif","t":"Infection ostéo-articulaire : connaître les arguments diagnostiques","q":"Quels sont les principaux signes cliniques suggérant une infection ostéo-articulaire (IOA) chez l'enfant ?","a":"<ul><li><strong>Fièvre</strong> (avec ou sans altération de l'état général).</li><li><strong>Impotence fonctionnelle</strong> : se manifeste par un refus d'appui ou une boiterie d'esquive franche.</li><li>Si <strong>arthrite septique</strong> : articulation chaude, douloureuse, avec une position antalgique et une mobilisation impossible.</li><li>Si <strong>ostéomyélite</strong> : douleur métaphysaire, palpation très douloureuse, et parfois un œdème localisé.</li><li>Recherche d'une <strong>porte d'entrée</strong> : plaie, varicelle surinfectée, infection ORL récente.</li></ul>"},{"i":"983ac59c41a7","n":54,"o":"54-6","u":"Diagnostic positif","t":"Infection ostéo-articulaire : connaître les arguments diagnostiques","q":"Comment doit-on évoquer initialement une infection ostéo-articulaire (IOA) chez l'enfant ?","a":"<p>Une infection ostéo-articulaire (IOA) doit être évoquée systématiquement devant toute <strong>boiterie fébrile</strong> de l'enfant.</p>"},{"i":"b45ddf798cd9","n":54,"o":"54-6","u":"Diagnostic positif","t":"Infection ostéo-articulaire : connaître les arguments diagnostiques","q":"Quels sont les examens paracliniques clés pour le diagnostic d'une infection ostéo-articulaire (IOA) chez l'enfant ?","a":"<ul><li><strong>Biologie</strong> : <ul><li><strong>Hyperleucocytose à PNN</strong> à la NFS.</li><li>Augmentation de la <strong>CRP</strong> (marqueur le plus sensible).</li><li>Augmentation de la VS (moins spécifique).</li><li><strong>Hémocultures ×2</strong> (avant antibiothérapie), souvent positives.</li></ul></li><li><strong>Imagerie</strong> : <ul><li><strong>Radiographies standard</strong> : normales au début, signes retardés.</li><li><strong>Échographie</strong> : épaississement des parties molles, abcès sous-périosté, épanchement articulaire.</li><li><strong>IRM</strong> : examen de choix pour le diagnostic précoce de l'ostéomyélite et la recherche de complications.</li><li><strong>Scintigraphie</strong> : si douleur difficile à localiser.</li></ul></li><li><strong>Prélèvements bactériologiques</strong> indispensables avant antibiothérapie : <ul><li>Hémocultures (×2).</li><li>Ponction articulaire (sous AG) si arthrite pour analyse cytobactériologique.</li><li>Prélèvement du pus d'un abcès sous-périosté.</li></ul></li></ul>"},{"i":"ed3e37d56437","n":54,"o":"54-6","u":"Diagnostic positif","t":"Infection ostéo-articulaire : connaître les arguments diagnostiques","q":"Quel piège diagnostique est à connaître concernant la radiographie standard dans le diagnostic de l'ostéomyélite chez l'enfant ?","a":"<p>Une <strong>radiographie standard normale</strong> n'élimine absolument pas une ostéomyélite à la phase précoce, car les signes radiologiques apparaissent de façon retardée.</p>"}]};